#
# Rule:        CKV_AWS_44 (checkov 3.3.16)
# Applies to:  aws_neptune_cluster
# Read with:   aws_api_assets (declarative spec, tools/api_specs.yml)
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_44'] || []

control 'CKV_AWS_44' do
  title 'Ensure Neptune storage is securely encrypted'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_neptune_cluster resources that actually exist, enumerated
    through the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    Neptune storage encryption can only be set when the cluster is created,
    so an unencrypted graph database stays unencrypted for its whole life.
    The graph itself is usually identity and relationship data, and it sits
    on volumes and in automated snapshots that outlive the cluster.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_neptune_cluster: storage_encrypted is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_neptune_cluster:

      resource "aws_neptune_cluster" "graph" {
        cluster_identifier                  = "graph"
        engine                              = "neptune"
        storage_encrypted                   = true
        kms_key_arn                         = aws_kms_key.neptune.arn
        backup_retention_period             = 7
        iam_database_authentication_enabled = true
        copy_tags_to_snapshot               = true
        skip_final_snapshot                 = false
        final_snapshot_identifier           = "graph-final"
      }

    Out of band — aws_neptune_cluster:

      There is no in-place fix. Neptune storage encryption is set at creation
      only. Take a snapshot, restore it into a new encrypted cluster, then
      cut over and delete the original:
      aws neptune create-db-cluster-snapshot --db-cluster-identifier graph --db-cluster-snapshot-identifier graph-migrate
      aws neptune restore-db-cluster-from-snapshot --db-cluster-identifier graph-enc --snapshot-identifier graph-migrate --engine neptune --storage-encrypted --kms-key-id <key-arn>
  FIX

  tag checkov_id:            'CKV_AWS_44'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_neptune_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/neptune_cluster#storage-encrypted'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_neptune_cluster', regions: scan_regions)

  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets(exempt: exempt)
                   .reject { |a| a[:storage_encrypted].nil? }

  applicable = !in_scope.empty?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_neptune_cluster in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_neptune_cluster #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:storage_encrypted] }
      it { should eq true }
    end
  end
end
